"""Summarize bundle metadata without opening the listed files."""
import json


def summarize_manifest(text: str) -> dict:
    """Return bundle_id, file_count, and total_bytes from a JSON manifest.

    A manifest is an object with a nonempty string bundle_id and a files list.
    Each file is an object with a nonempty string path and a nonnegative
    integer size_bytes (booleans are invalid). An empty file list is valid.
    Invalid JSON or malformed metadata must raise ValueError. Extra fields
    are ignored. Paths are metadata only and must never be opened.
    """
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError(f'Invalid JSON: {e}')

    # Validate data is a dictionary, not array or null
    if not isinstance(data, dict):
        raise ValueError('Must be a JSON object, not array or null')

    # Validate bundle_id is a nonempty string
    if not isinstance(data.get('bundle_id'), str) or not data['bundle_id']:
        raise ValueError('bundle_id must be a nonempty string')

    # Validate files is a list
    files = data.get('files')
    if not isinstance(files, list):
        raise ValueError('files must be a list')

    file_count = 0
    total_bytes = 0

    for entry in files:
        # Validate path is a nonempty string
        if not isinstance(entry, dict):
            raise ValueError('file entry must be an object')

        if 'path' not in entry:
            raise ValueError('file entry must have a path')

        if not isinstance(entry['path'], str) or not entry['path']:
            raise ValueError('path must be a nonempty string')

        if 'size_bytes' not in entry:
            raise ValueError('file entry must have size_bytes')

        size_bytes = entry['size_bytes']

        # Validate size_bytes is a nonnegative integer (not bool, not float)
        if isinstance(size_bytes, bool):
            raise ValueError('size_bytes must be an integer, not a boolean')
        elif not isinstance(size_bytes, int):
            raise ValueError('size_bytes must be an integer')
        elif size_bytes < 0:
            raise ValueError('size_bytes must be nonnegative')

        file_count += 1
        total_bytes += size_bytes

    return {
        'bundle_id': data['bundle_id'],
        'file_count': file_count,
        'total_bytes': total_bytes
    }
